draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.fillStyle = '#ff9900';
  ctx.fillRect(0, H - 50, W, 50);
  ctx.fillStyle = '#ffe6cc';
  ctx.fillRect(0, H - 100, W, 50);
  ctx.fillStyle = '#ffffcc';
  ctx.fillRect(0, H - 150, W, 50);
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.moveTo(0, H - 100 + 25 * Math.sin(t));
  ctx.lineTo(W, H - 100 + 25 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(0, H - 50 + 25 * Math.cos(t));
  ctx.lineTo(W, H - 50 + 25 * Math.cos(t));
  ctx.stroke();
  ctx.restore();
}
